#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        SpecificVolume::new(v, SpecificVolumeUnit::CubicMeterPerKilogram),
        SpecificVolume::from_cubic_meters_per_kilogram(v)
    );
    assert_eq!(
        SpecificVolume::from_base(v).convert_to(SpecificVolumeUnit::CubicMeterPerKilogram),
        SpecificVolume::from_base(v).as_cubic_meters_per_kilogram()
    );
    assert_eq!(
        SpecificVolume::new(v, SpecificVolumeUnit::CubicMillimeterPerKilogram),
        SpecificVolume::from_cubic_millimeters_per_kilogram(v)
    );
    assert_eq!(
        SpecificVolume::from_base(v).convert_to(SpecificVolumeUnit::CubicMillimeterPerKilogram),
        SpecificVolume::from_base(v).as_cubic_millimeters_per_kilogram()
    );
    assert_eq!(
        SpecificVolume::new(v, SpecificVolumeUnit::CubicFootPerPound),
        SpecificVolume::from_cubic_feet_per_pound(v)
    );
    assert_eq!(
        SpecificVolume::from_base(v).convert_to(SpecificVolumeUnit::CubicFootPerPound),
        SpecificVolume::from_base(v).as_cubic_feet_per_pound()
    );
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = SpecificVolume::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            SpecificVolume::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in SpecificVolumeUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        SpecificVolume::from_base(0.0).auto_unit().unit,
        SpecificVolumeUnit::CubicMeterPerKilogram
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "m³/kg".parse::<SpecificVolumeUnit>(),
        Ok(SpecificVolumeUnit::CubicMeterPerKilogram)
    );
    assert_eq!(
        format!("2.5 {}", "m³/kg").parse::<SpecificVolume>(),
        Ok(SpecificVolume::new(
            2.5,
            SpecificVolumeUnit::CubicMeterPerKilogram
        ))
    );
    assert_eq!(
        "mm³/kg".parse::<SpecificVolumeUnit>(),
        Ok(SpecificVolumeUnit::CubicMillimeterPerKilogram)
    );
    assert_eq!(
        format!("2.5 {}", "mm³/kg").parse::<SpecificVolume>(),
        Ok(SpecificVolume::new(
            2.5,
            SpecificVolumeUnit::CubicMillimeterPerKilogram
        ))
    );
    assert_eq!(
        "ft³/lb".parse::<SpecificVolumeUnit>(),
        Ok(SpecificVolumeUnit::CubicFootPerPound)
    );
    assert_eq!(
        format!("2.5 {}", "ft³/lb").parse::<SpecificVolume>(),
        Ok(SpecificVolume::new(
            2.5,
            SpecificVolumeUnit::CubicFootPerPound
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<SpecificVolume>(),
        Err(ParseError::UnknownUnit)
    );
}

