#[test]
fn arithmetic_f64() {
    let a = SpecificVolume::from_base(6.0);
    let b = SpecificVolume::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = SpecificVolume::<i64>::from_base(7);
    let b = SpecificVolume::<i64>::from_base(2);
    assert_eq!(a + b, SpecificVolume::from_base(9));
    assert_eq!(a % b, SpecificVolume::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!(
        [a, b].iter().sum::<SpecificVolume<i64>>(),
        SpecificVolume::from_base(9)
    );
}
